S = "Hakeem Force Academy"
QS = [
(S, "In which year did India take the Kashmir issue to the UN Security Council?", ["1947", "1948", "1949", "1951"], 1,
 "India lodged its complaint under Article 35 of the UN Charter on 1 January 1948, after tribal and Pakistani forces entered Kashmir. The Security Council then set up the UN Commission for India and Pakistan (UNCIP).",
 "The UN-brokered ceasefire in Kashmir came into effect on 1 January 1949.", 1),
(S, "In which year did the First World War end?", ["1916", "1917", "1918", "1919"], 2,
 "The armistice with Germany took effect on 11 November 1918, ending the fighting. The Treaty of Versailles followed in 1919.",
 "The First World War began in 1914.", 1),
(S, "In which year did the Second World War end?", ["1944", "1945", "1946", "1947"], 1,
 "Germany surrendered in May 1945 and Japan surrendered in August and September 1945. The war therefore ended in 1945.",
 "The United Nations was founded in the same year, 1945.", 1),
(S, "In which year did the Cabinet Mission visit India?", ["1942", "1944", "1946", "1947"], 2,
 "The British Cabinet Mission arrived in India in March 1946 and announced its plan in May 1946. It proposed a loose federation, which the Congress and the Muslim League accepted only briefly.",
 "The Cabinet Mission consisted of Pethick-Lawrence, Stafford Cripps and A. V. Alexander.", 1),
(S, "In which year were the first Commonwealth Games (then called the British Empire Games) held?", ["1920", "1930", "1938", "1950"], 1,
 "The first British Empire Games were held in Hamilton, Canada, in 1930. They were later renamed the Commonwealth Games.",
 "The Games are held every four years and were named the British Commonwealth Games in 1970 and the Commonwealth Games in 1978.", 2),
(S, "In which year was the Non-Cooperation Movement launched in India?", ["1905", "1919", "1920", "1930"], 2,
 "Gandhi launched the Non-Cooperation Movement in 1920, supported by the Khilafat leaders, against British rule. Indians boycotted British courts, schools and goods.",
 "Gandhi suspended the movement in 1922 after the Chauri Chaura incident.", 1),
(S, "Around which year did the Ottoman Sultanate begin under Osman I?", ["1099", "1299", "1453", "1517"], 1,
 "Osman I founded the Ottoman state in Anatolia around 1299. It lasted until the sultanate was abolished in 1922.",
 "The Ottomans conquered Constantinople in 1453 under Sultan Muhammad II (Mehmed the Conqueror).", 1),
(S, "On which date did the United Nations officially come into existence?", ["26 June 1945", "24 October 1945", "10 January 1946", "1 January 1942"], 1,
 "The UN Charter came into force on 24 October 1945, after ratification by China, France, the USSR, the UK, the USA and most other signatories. This date is celebrated as United Nations Day.",
 "The UN Charter was signed in San Francisco on 26 June 1945.", 2),
(S, "On which date is Kashmir Day (Kashmir Solidarity Day) observed in Pakistan?", ["5 January", "5 February", "27 October", "13 July"], 1,
 "Pakistan observes Kashmir Solidarity Day on 5 February every year to express support for the people of Indian-held Kashmir.",
 "Kashmiris also observe 27 October as Black Day, the day Indian troops landed in Srinagar in 1947.", 1),
(S, "In which year did the Muhammadan Anglo-Oriental (MAO) College, Aligarh, begin as a college?", ["1857", "1867", "1877", "1920"], 2,
 "Sir Syed Ahmad Khan founded a school in 1875, which was raised to college level as the MAO College in 1877. Lord Lytton laid its foundation stone in 1877.",
 "The MAO College became Aligarh Muslim University in 1920.", 1),
(S, "In which Hijri year was the Ghazwa (Battle) of Tabuk fought?", ["6 AH", "8 AH", "9 AH", "10 AH"], 2,
 "The Ghazwa of Tabuk took place in 9 AH (630 CE) against the Byzantine threat on the northern frontier. The Prophet (PBUH) led about 30,000 Muslims, but no fighting occurred.",
 "Tabuk is also called Ghazwa-e-Usrah, the Expedition of Hardship, because of the heat and shortage of supplies.", 2),
(S, "In which Hijri year was Hajj made obligatory (according to the most commonly taught view)?", ["2 AH", "6 AH", "9 AH", "10 AH"], 2,
 "Most Pakistani textbooks teach that Hajj became obligatory in 9 AH. The Prophet (PBUH) sent Hazrat Abu Bakr to lead the Hajj that year.",
 "Sources differ, as some scholars give 6 AH or 10 AH; the Prophet (PBUH) performed his only Hajj, the Farewell Hajj, in 10 AH.", 1),
(S, "In which year was the state of Israel declared?", ["1945", "1947", "1948", "1956"], 2,
 "Israel declared independence on 14 May 1948, as the British Mandate over Palestine ended. The first Arab-Israeli war followed immediately.",
 "The UN General Assembly adopted the Palestine partition plan in November 1947.", 1),
(S, "In which year was the National Bank of Pakistan (NBP) established?", ["1947", "1948", "1949", "1952"], 2,
 "The National Bank of Pakistan was established in November 1949 to help finance the agricultural sector, notably the jute and cotton crops. It later acted as an agent of the State Bank.",
 "The State Bank of Pakistan began working earlier, on 1 July 1948.", 1),
(S, "In which battle was a blessed tooth of the Holy Prophet Muhammad (PBUH) broken?", ["Battle of Badr", "Battle of Uhud", "Battle of the Trench (Khandaq)", "Battle of Hunain"], 1,
 "In the Battle of Uhud (3 AH) the Prophet (PBUH) was struck and one of his lower front teeth (Rubaiyyah) was broken. He was also wounded in the face.",
 "Hazrat Hamza was martyred in the same battle.", 1),
(S, "In which year were the modern Olympic Games first held?", ["1856", "1896", "1900", "1912"], 1,
 "The first modern Olympic Games were held in Athens, Greece, in 1896. Baron Pierre de Coubertin revived the Games.",
 "The International Olympic Committee was founded in 1894.", 1),
(S, "In which Hijri year did the Holy Prophet (PBUH) deliver his Last (Farewell) Sermon?", ["8 AH", "9 AH", "10 AH", "11 AH"], 2,
 "The Prophet (PBUH) delivered the Last Sermon during the Farewell Hajj on 9 Dhul Hijjah, 10 AH (632 CE), at Arafat. He passed away in 11 AH.",
 "The sermon was delivered at Mount Arafat in the valley of Uranah.", 1),
(S, "In which year did Choudhary Rahmat Ali write the pamphlet 'Now or Never'?", ["1930", "1933", "1935", "1940"], 1,
 "Choudhary Rahmat Ali and his Cambridge colleagues issued the pamphlet 'Now or Never' in January 1933. It first proposed the name Pakistan for a Muslim homeland.",
 "Rahmat Ali is known as the person who coined the name Pakistan.", 1),
(S, "In which year was the Regional Cooperation for Development (RCD) established by Pakistan, Iran and Turkey?", ["1955", "1964", "1971", "1985"], 1,
 "The RCD was formally established in 1964 by Pakistan, Iran and Turkey to promote economic cooperation. It replaced the earlier CENTO-linked arrangements in the economic field.",
 "The RCD was succeeded by the Economic Cooperation Organization (ECO) in 1985.", 1),
(S, "In which year was the Second Battle of Panipat fought between Akbar's army and Hemu?", ["1526", "1556", "1576", "1761"], 1,
 "The Second Battle of Panipat was fought in 1556, when Akbar's general Bairam Khan defeated Hemu. It secured the Mughal throne for Akbar.",
 "The First Battle of Panipat in 1526 was won by Babur against Ibrahim Lodhi.", 1),
(S, "On what date did the State Bank of Pakistan begin operations?", ["14 August 1947", "1 July 1948", "11 September 1948", "1 January 1949"], 1,
 "The State Bank of Pakistan was inaugurated by Quaid-e-Azam Muhammad Ali Jinnah on 1 July 1948. It took over the work of the Reserve Bank of India for Pakistan.",
 "Its first governor was Zahid Hussain.", 1),
(S, "On what date was the 1973 Constitution of Pakistan enforced?", ["10 April 1973", "12 April 1973", "14 August 1973", "23 March 1973"], 2,
 "The National Assembly passed the Constitution on 10 April 1973, and it was enforced on 14 August 1973. It was authenticated by President Fazal Elahi Chaudhry.",
 "Zulfikar Ali Bhutto was the Prime Minister when the Constitution was enacted.", 1),
]
